#!/usr/bin/env bash
# Generated by build_bundle.py; inspect src/ for the implementation.
set -euo pipefail
umask 077
if ! command -v python3 >/dev/null; then
  echo '需要 Python >=3.9 与 PyYAML。Debian/Ubuntu: apt-get install python3 python3-yaml sshpass' >&2
  exit 1
fi
python3 -c 'import sys,yaml; assert sys.version_info >= (3,9)' || {
  echo '请先安装 python3-yaml；检查/dry-run 不自动安装依赖。' >&2; exit 1;
}
task_bundle_dir=$(mktemp -d /tmp/webscan-bundle.XXXXXXXX)
trap 'python3 -c "import shutil,sys; shutil.rmtree(sys.argv[1])" "$task_bundle_dir"' EXIT
python3 - "$task_bundle_dir" <<'PY_BUNDLE'
import base64,io,sys,zipfile
data=''
with zipfile.ZipFile(io.BytesIO(base64.b64decode(data))) as z:
    z.extractall(sys.argv[1])
PY_BUNDLE
python3 "$task_bundle_dir/src/installer.py" "$@"
